update public.events
set
  start_time = scheduled.start_time::timestamptz,
  end_time = scheduled.end_time::timestamptz
from (
  values
    ('00000000-0000-4000-8000-000000000021', '2026-10-05T16:00:00Z', '2026-10-05T18:00:00Z'),
    ('00000000-0000-4000-8000-000000000022', '2026-10-06T23:00:00Z', '2026-10-07T01:00:00Z'),
    ('00000000-0000-4000-8000-000000000023', '2026-10-07T18:00:00Z', '2026-10-07T20:00:00Z'),
    ('00000000-0000-4000-8000-000000000024', '2026-10-08T20:00:00Z', '2026-10-08T22:00:00Z'),
    ('00000000-0000-4000-8000-000000000025', '2026-10-09T15:00:00Z', '2026-10-09T16:30:00Z'),
    ('00000000-0000-4000-8000-000000000026', '2026-10-10T16:00:00Z', '2026-10-10T20:00:00Z'),
    ('00000000-0000-4000-8000-000000000027', '2026-10-11T01:00:00Z', '2026-10-11T03:00:00Z'),
    ('00000000-0000-4000-8000-000000000028', '2026-10-12T16:00:00Z', '2026-10-12T18:00:00Z'),
    ('00000000-0000-4000-8000-000000000029', '2026-10-13T15:00:00Z', '2026-10-13T16:30:00Z'),
    ('00000000-0000-4000-8000-000000000030', '2026-10-14T20:00:00Z', '2026-10-14T22:00:00Z')
) as scheduled(id, start_time, end_time)
where public.events.id = scheduled.id::uuid;
